"use client";
import { assets, facilityIcons, roomsDummyData } from "@/assets/assets";
import StarRating from "@/components/StarRating";
import Image from "next/image";
import { useRouter } from "next/navigation";
import { useState } from "react";

const CheckBox = ({ label, selected = false, onChange = () => { } }) => {
 return (
  <label className="flex gap-3 items-center cursor-pointer mt-2 text-sm">
   <input
    type="checkbox"
    checked={selected}
    onChange={(e) => onChange(e.target.checked, label)}
    className="cursor-pointer"
   />
   <span>{label}</span>
  </label>
 );
};

const RadioButton = ({ label, selected = false, onChange = () => { } }) => {
 return (
  <label className="flex gap-3 items-center cursor-pointer mt-2 text-sm">
   <input
    type="radio"
    name="sortOption"
    checked={selected}
    onChange={() => onChange(label)}
    className="cursor-pointer"
   />
   <span>{label}</span>
  </label>
 );
};

const Page = () => {
 const router = useRouter();
 const [openFilter, setOpenFilter] = useState(false);

 const roomTypes = ["Single Room", "Double Room", "Deluxe Room", "Family Suite"];

 const priceRanges = ["0 to 500", "500 to 1000", "1000 to 2000", "2000 to 3000"];

 const sortOptions = ["Price: Low to High", "Price: High to Low", "Newest First"];

 return (
  <div className="flex flex-col-reverse lg:flex-row items-start justify-between pt-28 md:pt-35 px-4 md:px-16 lg:px-24 xl:px-32">
   {/* Rooms */}
   <div>
    <div className="flex flex-col  text-left">
     <h1 className="front-playfair text-4xl md:text-[40px]">Hotel Rooms</h1>
     <p className="text-sm md:text-base text-gray-500/90 mt-2">
      Take advantage of our limited-time offers and special packages to
      enhance your stay and create unforgettable memories.
     </p>
    </div>

    {roomsDummyData.map((room) => (
     <div
      key={room._id}
      className="flex flex-col md:flex-row items-start py-10 gap-6 border-b border-gray-300 last:pb-30 last:border-0"
     >
      <Image
       onClick={() => {
        router.push("/rooms/" + room._id);
        window.scrollTo(0, 0);
       }}
       src={room.images[0]}
       width={100}
       height={100}
       className="h-65 md:w-1/2 w-full rounded-xl shadow-lg object-cover cursor-pointer"
       alt="room-image"
      />
      <div className="md:w-1/2 flex flex-col gap-2">
       <p className="text-gray-500">{room.hotel.city}</p>
       <p
        onClick={() => {
         router.push("/rooms/" + room._id);
         window.scrollTo(0, 0);
        }}
        className="text-gray-800 text-3xl front-playfair cursor-pointer"
       >
        {room.hotel.name}
       </p>
       <div className="flex items-center">
        <StarRating />
        <p className="ml-2">200+ review</p>
       </div>
       <div className="flex items-center gap-1 text-gray-500 mt-2 text-sm">
        <Image src={assets.locationIcon} alt="location" width={20} height={20} />
        <span>{room.hotel.address}</span>
       </div>
       {/* Rooms Amenities */}
       <div className="flex flex-wrap items-center mt-3 mb-6 gap-4">
        {room.amenities.map((item, index) => (
         <div
          key={index}
          className="flex items-center gap-2 px-3 py-2 rounded-lg bg-[#F5F5FF]/70"
         >
          <Image
           src={facilityIcons[item]}
           alt={item}
           width={20}
           height={20}
           className="w-6 h-6"
          />
          <p className="text-xs">{item}</p>
         </div>
        ))}
       </div>
       {/* Room Price Per Night */}
       <p className="text-xl front-medium text-gray-700">
        ${room.pricePerNight} /night
       </p>
      </div>
     </div>
    ))}
   </div>

   {/* Filters */}
   <div className="bg-white w-80 border border-gray-300 text-gray-600 mx-lg:mb-8 mini-lg:mt-16">
    <div
     className={`flex items-center justify-between px-5 py-2.5 min-lg:border-b border-gray-300 ${openFilter && "border-b"
      }`}
    >
     <p className="text-base font-medium text-gray-800">Filters</p>
     <div className="text-xs cursor-pointer">
      <span onClick={() => setOpenFilter(!openFilter)} className="lg:hidden">
       {openFilter ? "HIDE" : "SHOW"}
      </span>
      <span className="hidden lg:block">CLEAR</span>
     </div>
    </div>
    <div
     className={`${openFilter ? "h-auto" : "h-0 lg:h-auto"
      } overflow-hidden transition-all duration-700`}
    >
     {/* Popular Filters */}
     <div className="px-5 pt-5">
      <p className="font-medium text-gray-800 pb-2">Popular filters</p>
      {roomTypes.map((room, index) => (
       <CheckBox key={index} label={room} />
      ))}
     </div>

     {/* Price Range */}
     <div className="px-5 pt-5">
      <p className="font-medium text-gray-800 pb-2">Price Range</p>
      {priceRanges.map((range, index) => (
       <CheckBox key={index} label={`$ ${range}`} />
      ))}
     </div>
     {/* Sort By */}
     <div className="px-5 pt-5 pb-7">
      <p className="font-medium text-gray-800 pb-2">Sort By</p>
      {sortOptions.map((option, index) => (
       <RadioButton key={index} label={option} />
      ))}
     </div>
    </div>
   </div>
  </div>
 );
};

export default Page;
